WITH scored AS (SELECT id, session_id, event_type, page, event_time, duration_sec, AVG(duration_sec) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS duration_sec_avg_5, ROW_NUMBER() OVER (ORDER BY duration_sec, id) AS seq_no, ROW_NUMBER() OVER w_recent AS row_seq, AVG(duration_sec) OVER w_running AS duration_sec_avg_6_prior, FIRST_VALUE(duration_sec) IGNORE NULLS OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec FROM web_events WINDOW w_recent AS (PARTITION BY event_type ORDER BY duration_sec, id), w_running AS (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)), deduped AS (SELECT * FROM scored QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY row_seq NULLS FIRST, id) = 1), deduped_web_events AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY duration_sec DESC, id) AS rank_in_group FROM deduped QUALIFY rank_in_group = 1), with_dims AS (SELECT e.*, d.device FROM deduped_web_events e INNER JOIN sessions d ON e.session_id = d.id) SELECT id, event_type, page, event_time, duration_sec, seq_no, row_seq, first_known_duration_sec, rank_in_group FROM with_dims ORDER BY event_type
